// n8n Code Tool: builds a QuickChart image URL from the agent's input
let input = query;

// Parse the JSON text sent by the agent
if (typeof input === 'string') {
  try {
    input = JSON.parse(input);
  } catch (e) {
    return 'ERROR: input must be valid JSON with chart_type, title, series_name, labels and values.';
  }
}

const allowedTypes = ['bar', 'line', 'pie', 'doughnut', 'horizontalBar'];
const type = allowedTypes.includes(input.chart_type) ? input.chart_type : 'bar';
const title = input.title || 'Chart';
const seriesName = input.series_name || 'Value';
const labels = Array.isArray(input.labels) ? input.labels.map(String) : [];
const values = Array.isArray(input.values) ? input.values.map(Number) : [];

// Validate
if (labels.length === 0 || values.length === 0) {
  return 'ERROR: labels and values must be non-empty arrays.';
}
if (labels.length !== values.length) {
  return 'ERROR: labels and values must have the same length.';
}
if (values.some(v => Number.isNaN(v))) {
  return 'ERROR: values must all be numbers.';
}
if (labels.length > 12) {
  return 'ERROR: use at most 12 items. Send only the top 12.';
}

const palette = [
  '#4E79A7', '#F28E2B', '#E15759', '#76B7B2', '#59A14F', '#EDC948',
  '#B07AA1', '#FF9DA7', '#9C755F', '#BAB0AC', '#86BCB6', '#D37295'
];
const isPie = type === 'pie' || type === 'doughnut';

const config = {
  type: type,
  data: {
    labels: labels,
    datasets: [{
      label: seriesName,
      data: values,
      backgroundColor: isPie ? palette.slice(0, values.length) : palette[0],
      borderColor: isPie ? '#ffffff' : palette[0],
      fill: false
    }]
  },
  options: {
    title: { display: true, text: title, fontSize: 16 },
    legend: { display: isPie },
    plugins: {
      datalabels: {
        display: true,
        color: isPie ? '#ffffff' : '#333333',
        anchor: isPie ? 'center' : 'end',
        align: isPie ? 'center' : 'end',
        font: { weight: 'bold' }
      }
    }
  }
};

// Start the axis at zero for bar and line charts
if (!isPie) {
  const axis = { ticks: { beginAtZero: true } };
  config.options.scales = type === 'horizontalBar'
    ? { xAxes: [axis] }
    : { yAxes: [axis] };
}

const url = 'https://quickchart.io/chart?v=2&w=600&h=350&bkg=white&c='
  + encodeURIComponent(JSON.stringify(config));

return url;
